/* ---- PWT engine inline (auto-generated by scripts/inline-widget-engine.mjs; do not edit) ---- */

/**
 * PWT Embeddable Widget Engine — shared runtime for all embeddable
 * calculator widgets (widget roadmap "one engine, many widgets").
 *
 * Follows the bmi-widget.js pilot pattern: a single static script per
 * widget renders into #pwt-<name>-widget containers, fully client-side,
 * no iframe to our servers, works offline once loaded, with a visible
 * "Powered by" attribution link (the link-acquisition mechanism).
 *
 * This file is the shared library each widget script inlines. Keep it
 * framework-free and ES5-safe so any site can paste one <script> tag.
 */
(function () {
  'use strict';

  var SITE = 'https://practicalwebtools.com';

  // -- tiny DOM + style helpers ------------------------------------------

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    if (attrs) {
      for (var k in attrs) {
        if (!Object.prototype.hasOwnProperty.call(attrs, k)) continue;
        if (k === 'style') node.setAttribute('style', attrs[k]);
        else if (k === 'text') node.textContent = attrs[k];
        else if (k === 'html') node.innerHTML = attrs[k];
        else node.setAttribute(k, attrs[k]);
      }
    }
    (children || []).forEach(function (c) { if (c) node.appendChild(c); });
    return node;
  }

  function field(labelText, inputAttrs) {
    var id = inputAttrs.id;
    var label = el('label', {
      for: id,
      style: 'display:block;font-size:13px;color:#475569;margin-bottom:4px;font-weight:500',
      text: labelText,
    });
    var input = el('input', Object.assign({
      type: 'number',
      style: 'width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid #cbd5e1;border-radius:10px;font-size:15px;margin-bottom:12px;background:#fff;color:#0f172a',
    }, inputAttrs));
    return [label, input];
  }

  function outputBox(id) {
    return el('div', {
      id: id,
      style: 'padding:14px;border-radius:12px;background:#f1f5f9;text-align:center;font-size:15px;color:#334155;min-height:52px',
      text: '—',
    });
  }

  function num(v) {
    var n = parseFloat(v);
    return isFinite(n) ? n : NaN;
  }

  function fmt(n, places) {
    if (!isFinite(n)) return '—';
    var p = places == null ? 2 : places;
    var s = n.toFixed(p);
    // trim trailing zeros, keep at least `min` decimals (1 for plain fmt)
    s = s.replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '.0');
    return s.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  function money(n) {
    if (!isFinite(n)) return '—';
    return '$' + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  function pct(n) {
    if (!isFinite(n)) return '—';
    return fmt(n, 2) + '%';
  }

  // -- widget shell --------------------------------------------------------

  /**
   * Build the standard widget chrome: header, body, attribution footer.
   * @param {object} opts
   *   title: widget heading
   *   subtitle: small header text
   *   bodyBuilder: fn(container) — populates the body; returns update fn
   *   poweredByPath: tool path for the attribution link
   *   poweredByText: attribution anchor text suffix
   */
  function shell(opts) {
    var root = el('div', {
      style: 'max-width:420px;margin:0 auto;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;border:1px solid #e2e8f0;border-radius:16px;overflow:hidden;background:#fff',
    });

    var header = el('div', {
      style: 'padding:16px 20px;background:#1e293b;color:#fff',
    }, [
      el('div', { style: 'font-weight:700;font-size:16px', text: opts.title }),
      opts.subtitle ? el('div', { style: 'font-size:12px;opacity:.75;margin-top:2px', text: opts.subtitle }) : null,
    ]);

    var body = el('div', { style: 'padding:20px' });
    var update = opts.bodyBuilder(body) || function () {};

    var footer = el('div', {
      style: 'padding:10px 20px;border-top:1px solid #e2e8f0;font-size:11px;color:#94a3b8;text-align:center;background:#f8fafc',
      html: 'Powered by <a href="' + SITE + (opts.poweredByPath || '') + '" target="_blank" rel="noopener" style="color:#2563eb;text-decoration:none">Practical Web Tools</a>' + (opts.poweredByText ? ' — ' + opts.poweredByText : ''),
    });

    root.appendChild(header);
    root.appendChild(body);
    root.appendChild(footer);
    return { root: root, update: update };
  }

  /**
   * Boot a widget: find #pwt-<name>-widget (plus suffixed duplicates),
   * render a shell into each, wire inputs to their update functions.
   */
  function boot(name, mount) {
    function renderAll() {
      var host = document.getElementById('pwt-' + name + '-widget');
      if (host) {
        if (!host.dataset.pwtInit || host.children.length === 0) {
          host.dataset.pwtInit = '1';
          host.innerHTML = '';
          mount(host);
        }
      }
      var nodes = document.querySelectorAll('[id^="pwt-' + name + '-widget"]');
      nodes.forEach(function (n) {
        if (n && (!n.dataset.pwtInit || n.children.length === 0)) {
          n.dataset.pwtInit = '1';
          n.innerHTML = '';
          mount(n);
        }
      });
    }
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', renderAll);
    } else {
      renderAll();
    }
    // Framework pages (e.g. Next.js) hydrate AFTER DOMContentLoaded and can
    // wipe content injected into SSR'd containers. Re-check after load and
    // once more shortly after — idempotent via the children check above.
    window.addEventListener('load', renderAll);
    setTimeout(renderAll, 1500);
  }

  // -- exports -------------------------------------------------------------

  window.PWTWidget = {
    el: el,
    field: field,
    outputBox: outputBox,
    shell: shell,
    boot: boot,
    num: num,
    fmt: fmt,
    money: money,
    pct: pct,
    SITE: SITE,
  };
})();

/**
 * Embeddable Calorie / TDEE Calculator widget (Mifflin-St Jeor).
 * Usage:
 *   <div id="pwt-calorie-widget"></div>
 *   <script src="https://practicalwebtools.com/embed/calorie-widget.js" defer></script>
 */
(function () {
  'use strict';
  var E = window.PWTWidget;

  E.boot('calorie', function (host) {
    var inputs = {};
    var out;

    var built = E.shell({
      title: 'Calorie Calculator',
      subtitle: 'Daily calories (TDEE) — Mifflin-St Jeor',
      poweredByPath: '/health/calorie-calculator',
      poweredByText: 'free calorie calculator',
      bodyBuilder: function (body) {
        var rows = [
          E.field('Age', { id: 'pwt-cal-age', value: '30', min: '10', max: '100' }),
          E.field('Weight (kg)', { id: 'pwt-cal-w', value: '70', min: '20', max: '300', step: '0.1' }),
          E.field('Height (cm)', { id: 'pwt-cal-h', value: '170', min: '100', max: '230' }),
        ];
        rows.forEach(function (pair) {
          pair.forEach(function (n) { body.appendChild(n); });
          inputs[pair[1].id] = pair[1];
        });

        var label = E.el('label', { style: 'display:block;font-size:13px;color:#475569;margin-bottom:4px;font-weight:500', text: 'Sex' });
        var sex = E.el('select', { id: 'pwt-cal-sex', style: 'width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid #cbd5e1;border-radius:10px;font-size:15px;margin-bottom:12px;background:#fff;color:#0f172a' }, []);
        ['male', 'female'].forEach(function (v) {
          var o = E.el('option', { value: v });
          o.textContent = v === 'male' ? 'Male' : 'Female';
          sex.appendChild(o);
        });
        body.appendChild(label); body.appendChild(sex);
        inputs[sex.id] = sex;

        var label2 = E.el('label', { style: 'display:block;font-size:13px;color:#475569;margin-bottom:4px;font-weight:500', text: 'Activity level' });
        var act = E.el('select', { id: 'pwt-cal-act', style: 'width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid #cbd5e1;border-radius:10px;font-size:15px;margin-bottom:12px;background:#fff;color:#0f172a' }, []);
        [
          ['1.2', 'Sedentary (desk job)'],
          ['1.375', 'Light (1–3 days/wk)'],
          ['1.55', 'Moderate (3–5 days/wk)'],
          ['1.725', 'Very active (6–7 days/wk)'],
          ['1.9', 'Athlete (2× daily)'],
        ].forEach(function (pair) {
          var o = E.el('option', { value: pair[0] });
          o.textContent = pair[1];
          act.appendChild(o);
        });
        body.appendChild(label2); body.appendChild(act);
        inputs[act.id] = act;

        out = E.outputBox('pwt-cal-out');
        body.appendChild(out);
        return update;
      },
    });

    function update() {
      var age = E.num(inputs['pwt-cal-age'].value);
      var w = E.num(inputs['pwt-cal-w'].value);
      var h = E.num(inputs['pwt-cal-h'].value);
      var sex = inputs['pwt-cal-sex'].value;
      var act = E.num(inputs['pwt-cal-act'].value);
      if (!(age > 0) || !(w > 0) || !(h > 0) || !isFinite(act)) {
        out.innerHTML = '<span style="color:#94a3b8">Enter your details</span>';
        return;
      }
      var bmr = 10 * w + 6.25 * h - 5 * age + (sex === 'male' ? 5 : -161);
      var tdee = bmr * act;
      out.innerHTML =
        '<div style="font-size:26px;font-weight:800;color:#1e293b">' + E.fmt(tdee, 0) + ' <span style="font-size:13px;font-weight:600;color:#64748b">kcal/day</span></div>' +
        '<div style="font-size:12px;color:#64748b;margin-top:4px">BMR ' + E.fmt(bmr, 0) + ' kcal · mild loss ' + E.fmt(tdee - 250, 0) + ' · loss ' + E.fmt(tdee - 500, 0) + '</div>';
    }

    host.appendChild(built.root);
    Object.keys(inputs).forEach(function (id) {
      inputs[id].addEventListener('input', update);
      inputs[id].addEventListener('change', update);
    });
    update();
  });
})();
